RSpec.describe Timekeeping::Handoff::ReportDirectory do
  # "Source intents are saved at the checkpoint and reused on resume, and deleting or changing a terminal intent
  # after the checkpoint makes reconcile report a difference."
  # A baseline edited between runs (here: a terminal intent removed from the saved file) would hide exactly that
  # deletion, so a file whose text no longer matches the digest stored at the checkpoint must be refused.
  it "refuses a saved source intents file that was edited after it was written, even when the edit is valid JSON" do
    Dir.mktmpdir do |root|
      directory = described_class.new(root:, generation: 2)
      rows = [1, 2].map do |id|
        {
          "id" => id, "company_id" => 11, "invoice_id" => 100 + id,
          "operation_id" => format("00000000-0000-0000-0000-%012d", id), "generation" => 1,
          "desired_entry_ids" => [id, id + 10], "disposition" => "active", "state" => "committed",
          "created_at" => Time.utc(2026, 10, 30, 12, 0, 0, 123_456), "finished_at" => Time.utc(2026, 10, 30, 12, 5, 0)
        }
      end

      digest = directory.write_source_intents(rows)
      expect(directory.read_source_intents(digest:)).to eq(rows)

      intents_file = directory.path.join("source_intents.json")
      original = intents_file.read
      edited = original.sub("00000000-0000-0000-0000-000000000002", "00000000-0000-0000-0000-000000000009")
      expect(edited).not_to eq(original)
      intents_file.write(edited)

      expect { directory.read_source_intents(digest:) }.to raise_error(described_class::Unreadable)

      intents_file.write(original[0, original.length / 2])
      expect { directory.read_source_intents(digest:) }.to raise_error(described_class::Unreadable)

      intents_file.delete
      expect { directory.read_source_intents(digest:) }.to raise_error(described_class::Unreadable)
    end
  end
end

